'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const life=[['🌿','Grass','草'],['🐇','Rabbit','兔'],['🦊','Fox','狐狸'],['🌳','Oak leaves','橡樹葉'],['🐛','Caterpillar','毛毛蟲'],['🐦','Blue tit','藍山雀'],['🦠','Phytoplankton','浮游植物'],['🦐','Antarctic krill','南極磷蝦'],['🐋','Blue whale','藍鯨']];
const orders=[[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]];
let variant=OrionProgress.variant('foodchains'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,chosen=[],solved=false,hintDepth=0,state='ready',saveFailed=false;
function habitat(v=variant,s=stage){return orders[v][s];}
function target(v=variant,s=stage){const b=habitat(v,s)*3;return [b,b+1,b+2];}
function deck(v=variant,s=stage){const h=habitat(v,s),other=(h+1+(v%2))%3,a=[h*3+2,other*3,h*3,other*3+2,h*3+1,other*3+1];return a.slice(v).concat(a.slice(0,v));}
function name(i){return t(life[i][1],life[i][2]);}
function place(){return [t('Meadow','草地'),t('Oak woodland','橡樹林'),t('Southern Ocean','南冰洋')][habitat()];}
function resetTrial(){chosen=[];solved=false;hintDepth=0;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('foodchains')){variant=v;stage=0;resetTrial();}
function choose(i){if(solved||!Number.isInteger(i)||!deck().includes(i)||chosen.includes(i)||chosen.length>=3)return;chosen.push(i);state='ready';render();}
function remove(i){if(solved||!Number.isInteger(i)||i<0||i>=chosen.length)return;chosen.splice(i,1);state='ready';render();}
function matches(){return chosen.length===3&&chosen.every((n,i)=>n===target()[i]);}
function check(){if(solved)return;if(chosen.length!==3){state='incomplete';render();return;}if(!matches()){state='wrong';render();return;}solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('connection');render();if(stage<2)$('next').focus();}
function hints(){const a=target();return[t('Start with a living thing that uses light to make food. Follow the energy to an eater, then to another eater.','先找利用光製造養分的生物。跟着能量，連到吃它的生物，再連到下一個消費者。'),t(`This tapestry belongs to the ${place()}. ${name(a[1])} eats ${name(a[0])}; ${name(a[2])} eats ${name(a[1])}.`,`這幅是${place()}織錦。${name(a[1])}吃${name(a[0])}；${name(a[2])}吃${name(a[1])}。`),t('Try this order: ','試試這個次序：')+a.map(name).join(' → ')];}
function render(){const complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Living Tapestry · Orion','生命織錦寶庫 · Orion');$('stageTitle').textContent=t(`Tapestry ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 幅織錦 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Tapestries restored · ${count} / 3`,`已修復 ${count} / 3 幅織錦`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('chain').classList.toggle('success-flow',solved);$('chain').innerHTML=Array.from({length:3},(_,i)=>{const n=chosen[i];return (i?'<span class="arrow" aria-hidden="true">→</span>':'')+`<button id="slot${i}" class="${n===undefined?'slot':''}" ${n===undefined||solved?'disabled':''} aria-label="${n===undefined?t(`Empty place ${i+1}`,`空位 ${i+1}`):t(`Remove ${name(n)} from place ${i+1}`,`從位置 ${i+1} 移除${name(n)}`)}"><span class="icon" aria-hidden="true">${n===undefined?'？':life[n][0]}</span>${n===undefined?t(`Place ${i+1}`,`位置 ${i+1}`):name(n)}</button>`;}).join('');for(let i=0;i<3;i++)$('slot'+i).onclick=()=>remove(i);
$('cards').innerHTML=deck().map(n=>`<button id="card${n}" class="card" ${solved||chosen.includes(n)||chosen.length===3?'disabled':''} aria-label="${t(`Add ${name(n)} to the chain`,`把${name(n)}加入食物鏈`)}"><span class="icon" aria-hidden="true">${life[n][0]}</span><span>${name(n)}</span></button>`).join('');deck().forEach(n=>$('card'+n).onclick=()=>choose(n));
$('arrowLabel').textContent=t('→ Energy passes from food to its eater. Icons are symbols, not life-size pictures.','→ 能量由食物傳到吃它的生物。圖示是符號，不按真實大小繪畫。');$('goal').innerHTML=`<strong>${place()}</strong>`+t('Restore this habitat’s three-link food chain.','修復這個棲地的三環食物鏈。');
$('reading').textContent=solved?t('☀ Light → food-making organism → consumer → consumer. The arrows follow food energy.','☀ 光 → 製造養分的生物 → 消費者 → 消費者。箭頭追蹤食物能量。'):t('Your chain: ','你的食物鏈：')+(chosen.length?chosen.map(name).join(' → '):t('Choose a first card.','選第一張圖卡。'));
const msg={ready:t('Build a chain, then weave it. You can change your choices without losing anything.','排好食物鏈，再把它織合。你可以隨時修改，不會失去任何東西。'),incomplete:t('The tapestry needs three cards. Fill all three places first.','織錦需要三張圖卡。先填滿三個位置。'),wrong:chosen.some(n=>!target().includes(n))?t('Some cards belong to another tapestry. Look for this habitat’s feeding links.','有些圖卡屬於另一幅織錦。找找這個棲地的攝食關係。'):t('These belong here, but the order needs changing. Arrows go from food to the one eating it.','這些生物都屬於這裡，但次序需要改變。箭頭由食物指向吃它的生物。'),success:t('A living connection! Food energy links the three organisms.','生命連起來了！食物能量把三種生物連繫起來。')};$('feedback').textContent=msg[state];
for(const id of ['check','retry'])$(id).hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('connection')?t('Connection Sigil saved in your collection.','連繫符印已存入收藏。'):'';
}
$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('card'+deck()[0]).focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('foodchains',variant);observedVariant=OrionProgress.variant('foodchains');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('connection');render();};
function syncProgress(){const v=OrionProgress.variant('foodchains'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('connection')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
